// The main tool session may legitimately reuse original B's pool PID. It
// is only execution evidence, never the fresh fixture/restoration authority.
const mainFixture=oneRow(qualificationResult.statements[0]),mainHeld=oneRow(qualificationResult.statements[1]);
requireThat(Number.isSafeInteger(mainFixture.backendPid)&&mainFixture.backendPid>0
 &&mainHeld.holderGranted===true&&mainHeld.holderPid===receipt.holderIdentity.backendPid
 &&mainHeld.precedingGranted===true&&mainHeld.precedingCount===0&&mainHeld.writerPid===mainFixture.backendPid,'MCP_SECOND_MAIN_PROOF_REQUIRED');
const fresh=qualificationResult.rollbackVerification;
requireThat(fresh?.connectedFresh===true&&fresh.database==='cloudtms_test_clone'
 &&statementSequence(fresh.statements,2)&&fresh.statements.every(s=>!s.error),'MCP_SECOND_FRESH_ROLLBACK_REQUIRED');
const fixtureProof=oneRow(fresh.statements[0]),held=oneRow(fresh.statements[1]);
requireThat(held.holderGranted===true&&held.holderPid===receipt.holderIdentity.backendPid&&held.precedingGranted===true&&held.precedingCount===0
 &&held.writerPid===fixtureProof.backendPid,'MCP_FIXTURE_PROOF_HOLDER_REQUIRED');
requireThat(fixtureProof.connectedFresh===true&&Number.isSafeInteger(fixtureProof.backendPid)&&fixtureProof.backendPid>0
 &&![stage.transaction.backendPid,receipt.holderIdentity.backendPid,beforePacket.peer.readerPid,afterPacket.peer.readerPid,
   mainFixture.backendPid].includes(fixtureProof.backendPid),'MCP_SECOND_VERIFICATION_PID_NOT_FRESH');
